import{z as A,x as l,o as E,c,q as B,j as r,D as a,d as i,s as o,S as t}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"拍卖理论的深化","description":"","frontmatter":{"title":"拍卖理论的深化","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ct-auction-theory-deep.md","filePath":"econ/ct-auction-theory-deep.md","lastUpdated":1791413859000}'),s={name:"econ/ct-auction-theory-deep.md"};function C(p,e,d,h,u,m){const n=l("Mermaid");return E(),c("div",null,[e[2]||(e[2]=B('<h1 id="拍卖理论的深化" tabindex="-1">拍卖理论的深化 <a class="header-anchor" href="#拍卖理论的深化" aria-label="Permalink to &quot;拍卖理论的深化&quot;">​</a></h1><div class="epigraph"><p>收入等价说标准拍卖一样赚钱；它的每一个前提，背后都是一个真实存在的市场。</p><footer>—— 据 Milgrom and Weber, Econometrica, 1982；Maskin and Riley, Review of Economic Studies, 2000 整理</footer></div><p><a href="/econ/ct-multilateral-mechanism">上一课</a>把人数与合谋写进机制，本课回到最成熟的应用场：拍卖。基础课已把 IPV 风险中性的基准写满——<a href="/econ/ipv-first-price">一价遮挡</a>、<a href="/econ/second-price-vickrey">二价真话</a>、<a href="/econ/revenue-equivalence">收入等价</a>、<a href="/econ/auction-reserve">保留价</a>、<a href="/econ/myerson-virtual-value">虚拟价值</a>，并各自开了口：<a href="/econ/winner-curse">共同价值</a>与<a href="/econ/all-pay-auction">全支付</a>。本课把收入等价的四个前提逐个拧开，看哪个方向的现实把哪种拍卖推上舞台，再补上多物品、进入与合谋。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>收入等价不是定理的终点，是一张检查清单：风险中性、私人价值独立、竞标者对称、人数外生，外加预算不约束、无合谋。基准课的「都一样赚钱」只在清单全绿时成立；真实拍卖市场几乎总有一项是红的。石油租约里估值相关联，采购里成本结构不对称，破产资产竞买人兜里钱不一样多，频谱拍卖里进入本身是决策。把红的项与对应的修正对上号，才谈得上选机制——否则只是在错基准旁边做装饰性的保留价。</p><h3 id="四个前提-四个市场" tabindex="-1">四个前提，四个市场 <a class="header-anchor" href="#四个前提-四个市场" aria-label="Permalink to &quot;四个前提，四个市场&quot;">​</a></h3><p>风险厌恶：一价拍卖里输赢风险由竞标者自担，怕输的人抬价避险，一价期望收入超过二价，卖方该选一价；同时风险厌恶削弱高保留价的抽租力——<a href="/econ/auction-reserve">保留价</a>的最优解假定风险中性，这里要重算。关联：估值互相牵连时，信息有正的租金价值，公开环节让退出行为泄露信息，Milgrom 与 Weber 在 1982 年的关联原理给出排序：英式不低于二价、二价不低于一价——<a href="/econ/winner-curse">赢家诅咒</a>课已给直觉，这里钉排序本身。非对称：强弱竞标者同场，弱者的存在让强者压价、收入反而受损，Maskin 与 Riley 在 2000 年的处理是歧视性的保留与 handicap——公平与收入在这里正面冲突。</p><p><span class="marginnote">术语翻译：「handicap」就是给强弱同场时「让子」——对弱竞标者降低入场门槛，或给强者单独设更高的保留条件，人为把两类拉开，防止弱者的存在白白压低强者的出价、拖累总收入。</span></p><p><span class="marginnote">关联原理的工程含义：把关联信息搬进公开环节通常更赚钱，但公开同时也方便合谋的信号传递——收入理论的两个方向压在同一个按钮上，选不选公开要看对手方的合作能力。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设计问题有统一写法：直接机制给每个报告定配置概率 \\(q_i(b)\\) 与支付 \\(t_i(b)\\)，IC 与 IR 为约束，目标为期望收入；包络把支付从搜索里删掉（<a href="/econ/implementability-envelope">可实施性与包络</a>已备），收入等价只是包络的推论，Myerson 的虚拟价值是拧开「优化收入」旋钮后的解。进入内生时，保留价的算式要加上进入反应：高保留价吓退边际竞标者，减员可能吞掉抽租收益——<a href="/econ/auction-structural-estimation">拍卖的结构估计</a>已把参与内生列为反演前提，设计与估计在这里对上同一本账。</p>',11)),(E(),r(t,null,{default:a(()=>[o(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CHECK%7B%22%E6%94%B6%E5%85%A5%E7%AD%89%E4%BB%B7%E5%89%8D%E6%8F%90%E6%A3%80%E6%9F%A5%22%7D%0A%20%20CHECK%20--%3E%7C%22%E9%A3%8E%E9%99%A9%E5%8E%8C%E6%81%B6%22%7C%20RA%5B%22%E4%B8%80%E4%BB%B7%E6%94%B6%E5%85%A5%E5%8D%A0%E4%BC%98%EF%BC%8C%E4%BF%9D%E7%95%99%E4%BB%B7%E9%87%8D%E7%AE%97%22%5D%0A%20%20CHECK%20--%3E%7C%22%E4%BC%B0%E5%80%BC%E5%85%B3%E8%81%94%22%7C%20LNK%5B%22%E5%85%AC%E5%BC%80%E7%8E%AF%E8%8A%82%E5%80%BC%E9%92%B1%EF%BC%9A%E8%8B%B1%E5%BC%8F%20%E2%89%A5%20%E4%BA%8C%E4%BB%B7%20%E2%89%A5%20%E4%B8%80%E4%BB%B7%22%5D%0A%20%20CHECK%20--%3E%7C%22%E4%B8%8D%E5%AF%B9%E7%A7%B0%22%7C%20ASY%5B%22handicap%20%E6%AD%A7%E8%A7%86%EF%BC%8C%E5%85%AC%E5%B9%B3%E4%B8%8E%E6%94%B6%E5%85%A5%E5%86%B2%E7%AA%81%22%5D%0A%20%20CHECK%20--%3E%7C%22%E8%BF%9B%E5%85%A5%E5%86%85%E7%94%9F%22%7C%20ENT%5B%22%E4%BF%9D%E7%95%99%E4%BB%B7%E4%B8%8A%E8%A6%81%E5%8A%A0%E8%BF%9B%E5%85%A5%E5%8F%8D%E5%BA%94%22%5D%0A%20%20RA%20--%3E%20DESIGN%5B%22%E6%8C%89%E7%BA%A2%E9%A1%B9%E9%80%89%E6%9C%BA%E5%88%B6%22%5D%0A%20%20LNK%20--%3E%20DESIGN%0A%20%20ASY%20--%3E%20DESIGN%0A%20%20ENT%20--%3E%20DESIGN%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=B('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>多物品把基准的裂缝放大。同质多件、逐件向上叫，竞标者对边际件的需求在价格爬升中露出，Ausubel 在 2004 年的升价机制把这件披露做成激励兼容；异质多件想一次配齐则要组合出价——同报多件打包，二价推广就是<a href="/econ/vcg-pivot">VCG</a>的拍卖特例，但暴露问题随之而来：单件竞标者可能为拼不齐的套装付出高价，组合拍卖因此存在，也因此在复杂度上爆炸。合谋侧与<a href="/econ/collusion-cartel">卡特尔</a>的重复博弈口径接上：竞标集团内部靠分配机制维持纪律，让标与轮流压价有策略签名，在数据里可检验——<a href="/econ/se-auction-deep">结构估计深入</a>已把合谋报价当作数据问题。</p>',2)),(E(),r(t,null,{default:a(()=>[o(n,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E5%A4%9A%E4%BB%B6%E7%89%A9%E5%93%81%E5%BE%85%E5%94%AE%22%5D%20--%3E%20Q%7B%22%E7%89%A9%E5%93%81%E4%B9%8B%E9%97%B4%E6%9B%BF%E4%BB%A3%E8%BF%98%E6%98%AF%E4%BA%92%E8%A1%A5%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%9B%BF%E4%BB%A3%E6%80%A7%E5%A4%9F%22%7C%20ASC%5B%22%E9%80%90%E4%BB%B6%E5%8D%87%E4%BB%B7%EF%BC%9AAusubel%20%E9%9C%80%E6%B1%82%E6%8A%AB%E9%9C%B2%22%5D%0A%20%20ASC%20--%3E%20TRU%5B%22%E8%BE%B9%E9%99%85%E9%9C%80%E6%B1%82%E5%9C%A8%E7%88%AC%E4%BB%B7%E4%B8%AD%E6%9A%B4%E9%9C%B2%EF%BC%8C%E7%9C%9F%E8%AF%9D%E6%BF%80%E5%8A%B1%E5%85%BC%E5%AE%B9%22%5D%0A%20%20Q%20--%3E%7C%22%E4%BA%92%E8%A1%A5%22%7C%20COMB%5B%22%E7%BB%84%E5%90%88%E5%87%BA%E4%BB%B7%EF%BC%9A%E6%89%93%E5%8C%85%E7%AB%9E%E6%A0%87%22%5D%0A%20%20COMB%20--%3E%20EXP%5B%22%E5%8D%95%E4%BB%B6%E7%AB%9E%E6%A0%87%E8%80%85%E6%80%95%E6%8B%BC%E4%B8%8D%E9%BD%90%E5%A5%97%E8%A3%85%EF%BC%9A%E6%9A%B4%E9%9C%B2%E9%97%AE%E9%A2%98%22%5D%0A%20%20EXP%20--%3E%20CX%5B%22%E7%BB%84%E5%90%88%E6%8B%8D%E5%8D%96%E8%A7%A3%E5%86%B3%E6%9A%B4%E9%9C%B2%EF%BC%8C%E4%BD%86%E5%A4%8D%E6%9D%82%E5%BA%A6%E7%88%86%E7%82%B8%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[i(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=B('<p><span class="marginnote">数字实例：两件配套设备单独估价各 10 万、打包值 30 万。某竞标者分开出价：若两件各以 12 万落槌、他只抢到一件，就为半套付出了 12 万——高于单件价值的 10 万，多付的 2 万就是「暴露问题」的账。</span></p><p><span class="marginnote">Vickrey 在 1961 年的原文里就有多件雏形；此后四十年是把「真话占优」从单件搬进高维配置空间的历史，每搬一次都要重答一遍替代性够不够。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重推收入等价与虚拟价值的推导，也不展开<a href="/econ/all-pay-auction">全支付与消耗战</a>的混合策略细节；动态拍卖与库存约束是另一门课的份量。结构估计侧的前提检查——风险厌恶、不可观测异质、内生进入、共同价值——已在<a href="/econ/auction-structural-estimation">拍卖的结构估计</a>与<a href="/econ/se-auction-deep">深化</a>写满，引用不重写。均衡概念的口径不同，结论会翻——这是上一课多边机制的警告在拍卖场的回声。下一课把货币拿掉，看配置还剩什么语言。</p><p><span class="marginnote">常见误区：初学者容易把「收入等价」读成任何拍卖都一样赚钱。它只在风险中性、私人价值独立、对称、人数外生这几项全绿时有效；现实中几乎总有一项破裂，选机制前要逐项对清单，而不是直接套结论。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>收入等价的四前提各对应一个真实市场：风险厌恶、关联、不对称、内生进入。</li><li>风险厌恶抬一价收入、削保留价抽租；关联让公开环节值钱；不对称要 handicap。</li><li>多物品在替代性够时升价披露可行，组合拍卖解决暴露问题但付出复杂度。</li><li>合谋有策略签名，让标与轮流在出价数据里可检验，不能当竞争反演。</li><li>选机制先查清单：红项决定修正方向，装饰性保留价救不了错基准。</li><li>出处：Vickrey, <em>J. Finance</em> 1961；Myerson, <em>Math. Oper. Res.</em> 1981；Milgrom and Weber, <em>Econometrica</em> 1982；Maskin and Riley, <em>REStud</em> 2000；Ausubel, <em>AER</em> 2004。</li></ul>',7))])}const _=A(s,[["render",C]]);export{f as __pageData,_ as default};
